import {ranges,positionFor,axisTicks,prepareEvents,speedSections,speedColor} from './strip-model.js';
const $=(el,s)=>el.querySelector(s);
const distanceText=v=>v>=1000?(v/1000).toLocaleString('de-DE',{maximumFractionDigits:2})+' km':Math.round(v)+' m';
const element=(tag,cls,text)=>{const el=document.createElement(tag);el.className=cls;if(text!==undefined)el.textContent=text;return el;};
export class RouteStrip{
 constructor(host,{onSelect=()=>{},onResize=()=>{}}={}){
  this.host=host;this.onSelect=onSelect;this.onResize=onResize;this.data={events:[]};this.range=5000;this.size=0;this.follow=true;this.nodes=new Map();this.context=null;
  try{const s=JSON.parse(localStorage.getItem('rheinrail-strip-v2')||'{}');if(ranges.includes(s.range))this.range=s.range;if([0,1,2].includes(s.size))this.size=s.size;}catch{}
  host.className='route-strip';host.innerHTML=`<div class="strip-header"><div class="strip-heading"><small>HYBRID-STRECKENBAND V2</small><h2>Strecke voraus <span class="strip-follow-state">Mitlaufend</span></h2></div><div class="strip-readings"><span>Ist <b data-reading="speed">—</b></span><span>Strecke <b data-reading="trackSpeed">—</b></span><span>HUD <b data-reading="permittedSpeed">—</b></span><span>LZB zul. <b data-reading="lzbPermittedSpeed">—</b></span></div><div class="strip-controls"><label>Vorschau <select aria-label="Streckenband-Vorschau">${ranges.map(r=>`<option value="${r}">${r/1000} km</option>`).join('')}</select></label><button class="strip-now" title="Zur aktuellen Zugposition">◎ Jetzt</button><button class="strip-size" aria-label="Streckenband-Darstellungsgröße">Standard ↕</button></div></div><div class="strip-body"><div class="strip-labels" aria-hidden="true"><div class="strip-label-axis">AB ZUG</div><div class="strip-label-speed">Streckentempo</div><div class="strip-label-signal">Signale</div><div class="strip-label-station">Halte / Ziele</div><div class="strip-label-protection">LZB / PZB</div></div><div class="strip-scroll" tabindex="0" aria-label="Grafisches Streckenband, horizontal scrollbar"><div class="strip-surface"><div class="strip-ticks"></div><div class="strip-speed-unknown"><span>Keine Bereichsgrenzen verfügbar</span></div><div class="strip-sections"></div><div class="strip-signal-line"></div><div class="strip-station-line"></div><div class="strip-protection"><span>Keine Streckenabschnitte verfügbar</span></div><div class="strip-train" title="Aktuelle Zugposition – relative Entfernung 0 m">▶<span>JETZT</span></div><div class="strip-markers"></div></div></div></div><div class="strip-footer"><span class="strip-coverage"></span><span>Abstände relativ zum Zug · keine Streckenkilometrierung</span></div>`;
  this.scroll=$(host,'.strip-scroll');this.surface=$(host,'.strip-surface');$(host,'select').value=String(this.range);
  $(host,'select').onchange=e=>{const old=this.range,newRange=Number(e.target.value),oldLeft=this.scroll.scrollLeft;this.range=newRange;this.axisKey=null;this.draw();if(!this.follow)this.scroll.scrollLeft=oldLeft*old/newRange;this.save();};
  $(host,'.strip-now').onclick=()=>{this.setFollow(true);this.scroll.scrollTo({left:0,behavior:'smooth'});};
  $(host,'.strip-size').onclick=()=>{this.size=(this.size+1)%3;this.applySize();this.save();};
  this.scroll.addEventListener('wheel',e=>{this.setFollow(false);if(Math.abs(e.deltaY)>Math.abs(e.deltaX)){this.scroll.scrollLeft+=e.deltaY;e.preventDefault();}},{passive:false});
  this.scroll.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','PageUp','PageDown','Home','End'].includes(e.key))this.setFollow(false);});
  this.scroll.addEventListener('touchstart',()=>this.setFollow(false),{passive:true});
  this.scroll.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&!e.target.closest('button')){this.drag={x:e.clientX,left:this.scroll.scrollLeft,moved:false};this.scroll.setPointerCapture(e.pointerId);} });
  this.scroll.addEventListener('pointermove',e=>{if(this.drag){const delta=e.clientX-this.drag.x;if(Math.abs(delta)>4){this.drag.moved=true;this.setFollow(false);this.scroll.scrollLeft=this.drag.left-delta;}}});
  const end=()=>this.drag=null;this.scroll.addEventListener('pointerup',end);this.scroll.addEventListener('pointercancel',end);
  this.resize=new ResizeObserver(()=>{this.axisKey=null;this.draw();});this.resize.observe(this.scroll);this.applySize();
 }
 save(){try{localStorage.setItem('rheinrail-strip-v2',JSON.stringify({range:this.range,size:this.size}));}catch{}}
 setFollow(value){this.follow=value;$(this.host,'.strip-follow-state').textContent=value?'Mitlaufend':'Nachführung pausiert';this.host.classList.toggle('strip-paused',!value);}
 applySize(){this.host.dataset.size=['standard','expanded','minimized'][this.size];$(this.host,'.strip-size').textContent=['Standard ↕','Erweitert ↕','Minimiert ↕'][this.size];this.onResize();}
 update(data,context){if(this.context!==context){this.context=context;this.scroll.scrollLeft=0;this.setFollow(true);}this.data=data;this.draw();}
 draw(){
  const width=this.scroll.clientWidth;if(!width)return;const events=prepareEvents(this.data.events);const domain=Math.min(100000,Math.max(40000,...events.map(e=>e.distance+2000)));const fullWidth=positionFor(domain,this.range,width)+100;this.surface.style.width=fullWidth+'px';
  const key=[Math.round(width),this.range,domain].join(':');if(key!==this.axisKey){this.axisKey=key;const ticks=$(this.host,'.strip-ticks');ticks.replaceChildren();for(const tick of axisTicks(domain,this.range)){const el=element('div','strip-tick',tick.label);el.style.left=positionFor(tick.distance,this.range,width)+'px';ticks.append(el);}}
  for(const name of ['speed','trackSpeed','permittedSpeed','lzbPermittedSpeed']){$(this.host,`[data-reading="${name}"]`).textContent=(Number.isFinite(this.data[name])&&(name!=='lzbPermittedSpeed'||this.data.lzbActive===true)?Math.round(this.data[name])+' km/h':'—');}
  const sections=speedSections(this.data),lane=$(this.host,'.strip-sections');lane.replaceChildren();for(const section of sections){const el=element('div','strip-speed-section',Math.round(section.speed)+' km/h');const x=positionFor(section.start,this.range,width),end=positionFor(section.end,this.range,width);el.style.left=x+'px';el.style.width=Math.max(0,end-x)+'px';el.style.background=speedColor(section.speed);el.title=`Streckengeschwindigkeit ${Math.round(section.speed)} km/h · ${distanceText(section.start)} bis ${distanceText(section.end)} · aus gemeldeten API-Grenzen abgeleitet`;lane.append(el);}
  $(this.host,'.strip-speed-unknown span').textContent=sections.length?'Hinter der letzten Grenze: keine bestätigten Bereichsdaten':'Keine Bereichsgrenzen verfügbar';
  $(this.host,'.strip-speed-unknown').style.left=positionFor(sections.at(-1)?.end||0,this.range,width)+'px';
  const protection=this.data.lzbActive===true?'Aktuell LZB geführt':this.data.pzbActive===true?'Aktuell PZB aktiv':'Fahrzeugstatus nicht aktiv / unbekannt';$(this.host,'.strip-protection span').textContent='Keine Streckenabschnitte verfügbar · '+protection;
  const markerLayer=$(this.host,'.strip-markers'),wanted=new Set();const previous={signal:[-Infinity,-Infinity],station:[-Infinity,-Infinity],speed:[-Infinity,-Infinity]};
  for(const e of events){if(e.distance>domain)continue;const id=e.kind+':'+e.id;wanted.add(id);let button=this.nodes.get(id);if(!button){button=element('button','strip-marker strip-marker-'+e.kind);button.type='button';button.append(element('span','strip-symbol'),element('span','strip-event-name'),element('span','strip-event-distance'));button.onclick=()=>{const current=(this.data.events||[]).find(x=>x.id===button.dataset.eventId);if(current)this.onSelect(current);};this.nodes.set(id,button);markerLayer.append(button);}button.dataset.eventId=e.id;
   const x=positionFor(e.distance,this.range,width),slots=previous[e.kind];let slot=slots[0]<=slots[1]?0:1;if(x-slots[0]>120)slot=0;slots[slot]=x;button.style.left=x+'px';button.dataset.stack=String(slot);
   button.children[0].textContent=e.kind==='speed'?Math.round(e.speed):e.kind==='station'?'▤':'●';button.children[1].textContent=e.kind==='station'?e.name:e.kind==='speed'?(e.restriction==='TemporarySpeedLimit'?'Temporär':'Wechsel'):e.aspect||'Signal';button.children[2].textContent=distanceText(e.distance);button.title=e.name+' · '+distanceText(e.distance)+(e.speed!==undefined?' · '+Math.round(e.speed)+' km/h':'')+(e.aspect?' · '+e.aspect:'');button.setAttribute('aria-label',button.title);button.dataset.aspect=e.aspect==='Clear'?'clear':['Stop','Danger'].includes(e.aspect)?'stop':'unknown';
  }
  for(const [id,node] of this.nodes)if(!wanted.has(id)){node.remove();this.nodes.delete(id);}
  $(this.host,'.strip-coverage').textContent=events.length?`${events.filter(e=>e.kind==='signal').length} Signale · ${events.filter(e=>e.kind==='speed').length} Wechsel · ${events.filter(e=>e.kind==='station').length} TSW-Ziele`:'Keine vorausliegenden Streckendaten verfügbar';
  if(this.follow&&this.scroll.scrollLeft!==0)this.scroll.scrollLeft=0;
 }
}
